using System.Text;

using LibGit2CS.Repository;

using GitBlame = LibGit2CS.Blame.GitBlame;

namespace LibGit2CS.UnitTests.Blame;

/// <summary>
/// Buffer blame tests ported from libgit2's <c>tests/libgit2/blame/buffer.c</c>.
/// Each test creates a file blame for <c>b.txt</c> in <c>blametest.git</c>,
/// then calls <see cref="Blame.Buffer"/> with modified content and asserts
/// the resulting hunks.
/// </summary>
public sealed class BufferBlameTests : BlameGoldenBase, IAsyncDisposable
{
    private async Task<GitBlame> CreateFileBlameAsync()
    {
        GitRepository repo = await OpenBareFixtureRepoAsync("blametest.git");
        GitBlame blame = await repo.BlameFileAsync("b.txt");
        // Keep repo alive for the test duration — store it in a field
        _repoRef = repo;
        return blame;
    }

    private GitRepository? _repoRef;

    // buffer.c::4_edits
    [Fact]
    public async Task FourEdits()
    {
        using GitBlame fileBlame = await CreateFileBlameAsync();
        string buffer = "EEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEE\nEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEE\nxEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEE\nEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEE\nx\nBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBB\nxBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBB\nBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBB\nxBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBB\n\nCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCC\nCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCC\nCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCC\nCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCC\n\n";
        using GitBlame bufBlame = await GitBlame.BufferAsync(fileBlame, Encoding.UTF8.GetBytes(buffer), cancellationToken: TestContext.Current.CancellationToken);

        Assert.Equal(10, bufBlame.HunkCount);
        await BlameHunkVerifier.AssertHunkAsync(_repoRef!, bufBlame, 0, 1, 2, 0, "da237394", "b.txt");
        await BlameHunkVerifier.AssertHunkAsync(_repoRef!, bufBlame, 1, 3, 1, 0, "000000", "b.txt");
        await BlameHunkVerifier.AssertHunkAsync(_repoRef!, bufBlame, 2, 4, 1, 0, "da237394", "b.txt");
        await BlameHunkVerifier.AssertHunkAsync(_repoRef!, bufBlame, 3, 5, 1, 0, "000000", "b.txt");
        await BlameHunkVerifier.AssertHunkAsync(_repoRef!, bufBlame, 4, 6, 1, 0, "63d671eb", "b.txt");
        await BlameHunkVerifier.AssertHunkAsync(_repoRef!, bufBlame, 5, 7, 1, 0, "000000", "b.txt");
        await BlameHunkVerifier.AssertHunkAsync(_repoRef!, bufBlame, 6, 8, 1, 0, "63d671eb", "b.txt");
        await BlameHunkVerifier.AssertHunkAsync(_repoRef!, bufBlame, 7, 9, 1, 0, "000000", "b.txt");
        await BlameHunkVerifier.AssertHunkAsync(_repoRef!, bufBlame, 8, 10, 1, 0, "63d671eb", "b.txt");
        await BlameHunkVerifier.AssertHunkAsync(_repoRef!, bufBlame, 9, 11, 5, 0, "aa06ecca", "b.txt");
    }

    // buffer.c::two_added_lines_and_one_modified
    [Fact]
    public async Task TwoAddedLinesAndOneModified()
    {
        using GitBlame fileBlame = await CreateFileBlameAsync();
        string buffer = "EEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEE\nEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEE\nEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEE\nx\nEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEE\nx\nBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBB\nxBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBB\nBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBB\nBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBB\n\nCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCC\nCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCC\nCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCC\nCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCC\n\n";
        using GitBlame bufBlame = await GitBlame.BufferAsync(fileBlame, Encoding.UTF8.GetBytes(buffer), cancellationToken: TestContext.Current.CancellationToken);

        Assert.Equal(8, bufBlame.HunkCount);
        await BlameHunkVerifier.AssertHunkAsync(_repoRef!, bufBlame, 0, 1, 3, 0, "da237394", "b.txt");
        await BlameHunkVerifier.AssertHunkAsync(_repoRef!, bufBlame, 1, 4, 1, 0, "000000", "b.txt");
        await BlameHunkVerifier.AssertHunkAsync(_repoRef!, bufBlame, 2, 5, 1, 0, "da237394", "b.txt");
        await BlameHunkVerifier.AssertHunkAsync(_repoRef!, bufBlame, 3, 6, 1, 0, "000000", "b.txt");
        await BlameHunkVerifier.AssertHunkAsync(_repoRef!, bufBlame, 4, 7, 1, 0, "63d671eb", "b.txt");
        await BlameHunkVerifier.AssertHunkAsync(_repoRef!, bufBlame, 5, 8, 1, 0, "000000", "b.txt");
        await BlameHunkVerifier.AssertHunkAsync(_repoRef!, bufBlame, 6, 9, 3, 0, "63d671eb", "b.txt");
        await BlameHunkVerifier.AssertHunkAsync(_repoRef!, bufBlame, 7, 12, 5, 0, "aa06ecca", "b.txt");
    }

