    // buffer.c::add_lines_at_end
    [Fact]
    public async Task AddLinesAtEnd()
    {
        using GitBlame fileBlame = await CreateFileBlameAsync();
        string buffer = "EEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEE\nEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEE\nEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEE\nEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEEE\n\nBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBB\nBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBB\nBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBB\nBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBBB\n\nCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCC\nCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCC\nCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCC\nCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCC\n\nabc\ndef\n";
        using GitBlame bufBlame = await GitBlame.BufferAsync(fileBlame, Encoding.UTF8.GetBytes(buffer), cancellationToken: TestContext.Current.CancellationToken);

        Assert.Equal(5, bufBlame.HunkCount);
        await BlameHunkVerifier.AssertHunkAsync(_repoRef!, bufBlame, 0, 1, 4, 0, "da237394", "b.txt");
        await BlameHunkVerifier.AssertHunkAsync(_repoRef!, bufBlame, 1, 5, 1, 1, "b99f7ac0", "b.txt");
        await BlameHunkVerifier.AssertHunkAsync(_repoRef!, bufBlame, 2, 6, 5, 0, "63d671eb", "b.txt");
        await BlameHunkVerifier.AssertHunkAsync(_repoRef!, bufBlame, 3, 11, 5, 0, "aa06ecca", "b.txt");
        await BlameHunkVerifier.AssertHunkAsync(_repoRef!, bufBlame, 4, 16, 2, 0, "00000000", "b.txt");
    }

    public async ValueTask DisposeAsync()
    {
        if (_repoRef is not null)
        {
            await _repoRef.DisposeAsync();
        }
    }
}
